units.x4a = { kind: 'explore', title: 'الكسور المتكافئة', idea: 'أستعملُ النماذجَ للتوصّلِ إلى طريقةِ تكوينِ كسورٍ متكافئة.',
  intro: [{ h: 'قطعُ العدّ', p: 145, html: '<p>تُستعملُ الكسورُ عادةً لوصفِ العلاقةِ بينَ جزءٍ من مجموعةٍ من العناصرِ والمجموعةِ الكاملةِ لها. والكسورُ التي تشتركُ في العلاقةِ نفسِها بينَ الجزءِ والكلِّ تُسمّى <b>كسورًا متكافئة</b>: ' + fr(3, 5) + ' و' + fr(6, 10) + '</p>' + counters(3, 5, 1) + counters(6, 10, 2) + '<p>ويمكنُكَ أيضًا الحصولُ على كسورٍ متكافئةٍ بتجزئةِ مجموعةٍ كبيرةٍ إلى مجموعاتٍ أصغر، وتُسمّى عمليّةُ التجزئةِ هذه <b>تبسيطَ الكسر</b>.</p>' },
    { h: '🔴 أداةُ قطعِ العدّ', html: '<p class="meta">مثّلْ كسرًا، ثم أضفْ مجموعاتٍ متساويةً للحصولِ على كسرٍ مكافئ، أو جزّئْ لتبسيطِه.</p>', tool: el => counterTool(el, 2, 3) }],
  examples: [
    { tag: 'نشاط ١', title: 'كسرٌ مكافئٌ للكسر ٢/٣', p: 145, text: 'استعملْ قطعَ العدِّ للحصولِ على كسرٍ مكافئٍ للكسر ' + fr(2, 3), ans: { type: 'frac', v: '6/9', simplest: false }, ws: [['الخطوة ١', 'مثّلِ الكسرَ ' + fr(2, 3) + ' عن طريقِ تكوينِ مجموعةٍ من ٣ قطع، قطعتانِ منها حمراوان.' + counters(2, 3, 1)], ['الخطوة ٢', 'أضفْ مجموعتين أخريين من هذه المجموعاتِ المتساوية لتشكّلَ مجموعةً أكبر:' + counters(6, 9, 3)], ['الخطوة ٣', '٦ من ٩ أو ' + fr(6, 9) + ' من القطعِ في المجموعةِ الكبيرةِ حمراء؛ لذا أحدُ الكسورِ المكافئةِ للكسر ' + fr(2, 3) + ' هو ' + fr(6, 9), { q: 'كم قطعةً حمراءَ في المجموعةِ الكبيرة؟', o: ['٦', '٣', '٩'], a: '٦' }]] },
    ...[['أ', 3, 4], ['ب', 1, 3], ['ج', 2, 5], ['د', 5, 6]].map(([t, n, d]) => fnq('تحقّقْ ' + t, `استعملْ قطعَ العدِّ لتكتبَ ٣ كسورٍ مكافئةً للكسر ${fr(n, d)} (افصلْ بينها بالفاصلة «،»)`, raw => { const P = toW(raw).split(/[،;؛]/).map(s => parseFrac(s.trim())).filter(Boolean); if (P.length !== 3) return { empty: true, msg: 'اكتبْ ثلاثةَ كسور مثل ٢/٤ ، ٣/٦ ، ٤/٨' }; if (P.some(f => Math.abs(f.v - n / d) > 1e-9)) return { ok: false, msg: 'أحدُ الكسورِ لا يكافئُ ' + fr(n, d) }; if (new Set(P.map(f => f.d)).size < 3 || P.some(f => f.d === d)) return { ok: false, msg: 'اكتبْ ثلاثةَ كسورٍ مختلفةٍ غيرَ الكسرِ نفسِه.' }; return { ok: true }; }, [2, 3, 4].map(k => `${AR(n * k)}/${AR(d * k)}`).join('، '), { cfu: true, p: 145, kp: 'frac', mount: el => counterTool(el, n, d) })),
    { tag: 'نشاط ٢', title: 'كسرٌ أبسط', p: 146, text: 'استعملْ قطعَ العدِّ لتكوينِ كسرٍ مكافئٍ للكسر ' + fr(6, 12) + ' وأبسطَ منه.', ans: { type: 'frac', v: '3/6', simplest: false }, ws: [['الخطوة ١', 'مثّلِ الكسرَ ' + fr(6, 12) + ' باستعمالِ قطعِ العدّ.' + counters(6, 12, 1)], ['الخطوة ٢', 'وزّعْ قطعَ العدِّ مجموعاتٍ متساوية؛ بحيث تكونُ العلاقةُ بينَ عددِ القطعِ الحمراءِ والعددِ الكلّيِّ للقطعِ هي نفسَها في كلتا المجموعتين.' + counters(6, 12, 2)], ['الخطوة ٣', 'يوجدُ ٣ من ٦ أو ' + fr(3, 6) + ' من القطعِ الموجودةِ في كلِّ مجموعةٍ صغيرةٍ حمراء؛ وبناءً عليه يكونُ ' + fr(3, 6) + ' هو أحدَ الكسورِ المكافئةِ للكسر ' + fr(6, 12) + ' وأبسطَ منه.']] },
    ...[['هـ', 10, 16], ['و', 6, 21], ['ز', 8, 24], ['ح', 24, 30]].map(([t, n, d]) => fnq('تحقّقْ ' + t, `استعملْ قطعَ العدِّ لتعطيَ كسرًا أبسطَ يكافئُ ${fr(n, d)}`, raw => { const f = parseFrac(raw); if (!f) return { empty: true }; if (Math.abs(f.v - n / d) > 1e-9) return { ok: false, msg: 'هذا الكسرُ لا يكافئُ ' + fr(n, d) }; return f.d < d ? { ok: true } : { ok: false, msg: 'المطلوبُ كسرٌ أبسط (مقامُه أصغر).' }; }, fr(n / gcd(n, d), d / gcd(n, d)), { cfu: true, p: 146, kp: 'frac', mount: el => counterTool(el, n, d) }))],
  ex: [['🔍 حلّلِ النتائج', 146, [mcq('١', 'تمَّ في النشاط ١ الحصولُ على كسرٍ مكافئٍ بضمِّ مجموعاتٍ متساوية. فما العمليّةُ الحسابيّةُ التي يمثّلُها ذلك؟', ['الضرب', 'القسمة', 'الجمع', 'الطرح'], 0),
    fnq('٢', 'خمّنْ: استعملِ العمليّةَ التي وجدتَها في السؤال ١؛ لإيجادِ كسرٍ مكافئٍ للكسر ' + fr(7, 8) + ' وبرّرْ إجابتَك.', raw => { const f = parseFrac(raw); if (!f) return { empty: true }; return Math.abs(f.v - 7 / 8) < 1e-9 && f.d > 8 ? { ok: true } : { ok: false, msg: 'اضربِ البسطَ والمقامَ في العددِ نفسِه.' }; }, fr(14, 16) + ' أو ' + fr(21, 24), { kp: 'frac' }),
    mcq('٣', 'في النشاط ٢، تمَّ الحصولُ على كسرٍ مكافئٍ عن طريقِ تجزئةِ مجموعةٍ كبيرةٍ إلى مجموعاتٍ صغيرةٍ متساوية. فما العمليّةُ الحسابيّةُ التي استُعملتْ في ذلك؟', ['الضرب', 'القسمة', 'الجمع', 'الطرح'], 1),
    fnq('٤', 'خمّنْ: استعملِ العمليّةَ التي وجدتَها في السؤال ٣؛ لإيجادِ كسرٍ يكافئُ الكسرَ ' + fr(30, 40) + ' وبرّرْ إجابتَك.', raw => { const f = parseFrac(raw); if (!f) return { empty: true }; return Math.abs(f.v - .75) < 1e-9 && f.d < 40 ? { ok: true } : { ok: false, msg: 'اقسمِ البسطَ والمقامَ على العددِ نفسِه.' }; }, fr(3, 4) + ' (بالقسمةِ على ١٠)', { kp: 'frac' })]]] };

