      ...[[4, 10], [5, 12], [12, 20], [16, 44]].map(([n, d], i) => fnq(AR(29 + i), `اكتبْ كسرين مكافئين للكسر ${fr(n, d)} (افصلْ بينهما بالفاصلة «،»)`, raw => { const P = toW(raw).split(/[،;؛]/).map(s => parseFrac(s.trim())).filter(Boolean); if (P.length !== 2) return { empty: true, msg: 'اكتبْ كسرين مثل ٢/٤ ، ٣/٦' }; if (P.some(f => Math.abs(f.v - n / d) > 1e-9)) return { ok: false, msg: 'أحدُهما لا يكافئُ ' + fr(n, d) }; if (P[0].d === P[1].d || P.some(f => f.d === d)) return { ok: false, msg: 'اكتبْ كسرين مختلفين عن الكسرِ المعطى.' }; return { ok: true }; }, [n * 2 + '/' + d * 2, n * 3 + '/' + d * 3].map(F).join('، '), { kp: 'frac' })),
