/* ═════════ ٤-٤ خطّةُ حلِّ المسألة: إنشاءُ قائمةٍ منظّمة ═════════ */
const perms = a => a.length <= 1 ? [a] : a.flatMap((x, i) => perms([...a.slice(0, i), ...a.slice(i + 1)]).map(p => [x, ...p]));
function listTool(el, names = ['عمّار', 'أسعد', 'حمد', 'نايف']) {
  el.innerHTML = `<div class="meta">المسِ الأسماءَ بالترتيبِ لتكوينِ ترتيبٍ جديد، وسيُضافُ إلى القائمة. حاولْ إيجادَ جميعِ الترتيبات بطريقةٍ منظّمة.</div><div class="row names">${names.map(n => `<button class="btn s sm" data-n="${n}">${n}</button>`).join('')}<button class="btn sm" data-a="clr">↺</button></div><div class="cur big"></div><div class="meta cnt"></div><div class="plist"></div><button class="lnk" data-a="all">📋 أرني القائمةَ المنظّمةَ كاملة</button>`;
  let cur = [], found = new Set(); const total = perms(names).length;
  const upd = () => { $('.cur', el).textContent = cur.join(' ، ') || '…'; $('.cnt', el).textContent = `وجدتَ ${AR(found.size)} من ${AR(total)} ترتيبًا`; $('.plist', el).innerHTML = [...found].sort().map(s => `<span class="chip">${s.split('|').map(x => x[0]).join(' ')}</span>`).join(' '); if (found.size === total) star(1, 'أنشأتَ القائمةَ المنظّمة'); };
  $$('[data-n]', el).forEach(b => b.onclick = () => { if (cur.includes(b.dataset.n)) return; cur.push(b.dataset.n); if (cur.length === names.length) { found.add(cur.join('|')); setTimeout(() => { cur = []; upd(); }, 400); } upd(); });
  $('[data-a="clr"]', el).onclick = () => { cur = []; upd(); };
  $('[data-a="all"]', el).onclick = () => { $('.plist', el).innerHTML = names.map(f => `<div><b>القائمةُ التي تبدأُ بـ ${f[0]}:</b> ${perms(names.filter(x => x !== f)).map(p => [f, ...p].map(x => x[0]).join(' ')).join(' — ')}</div>`).join(''); };
  upd();
}
