/* ═════════ ٤-٥ المضاعفُ المشتركُ الأصغر ═════════ */
const multiples = (n, k = 6) => Array.from({ length: k }, (_, i) => n * (i + 1));
function multTool(el, a = 2, b = 3) {
  el.innerHTML = `<div class="row">${ansInput('العدد الأوّل', '70px')} و ${ansInput('العدد الثاني', '70px')}<button class="btn s sm" data-a="go">اعرضْ</button></div><div class="mlb"></div>`;
  const I = $$('input', el); I[0].value = AR(a); I[1].value = AR(b);
  const go = () => { const x = parseNum(I[0].value), y = parseNum(I[1].value); if (![x, y].every(v => Number.isInteger(v) && v > 0 && v <= 30)) return; const L = lcm(x, y), max = Math.max(15, Math.min(L * 2, 60)); const W = 360, X = v => 15 + v / max * 330;
    let g = `<line x1="5" x2="355" y1="70" y2="70" stroke="#333"/>`; for (let v = 0; v <= max; v++) g += `<line x1="${X(v)}" x2="${X(v)}" y1="66" y2="74" stroke="#333"/>` + ((max <= 20 || v % 5 === 0) ? `<text x="${X(v)}" y="88" font-size="9" text-anchor="middle">${AR(v)}</text>` : '');
    for (let v = x; v <= max; v += x) g += `<rect x="${X(v) - 4}" y="52" width="8" height="8" fill="#e84a3a"/>`; for (let v = y; v <= max; v += y) g += `<rect x="${X(v) - 4}" y="40" width="8" height="8" fill="#1a6ad0"/>`; g += `<circle cx="${X(L)}" cy="30" r="6" fill="none" stroke="#2f8f4a" stroke-width="2.5"/>`;
    $('.mlb', el).innerHTML = `<svg viewBox="0 0 ${W} 95" style="width:100%;max-width:460px;direction:ltr">${g}</svg><table class="tb"><tr><th>مضاعفاتُ ${AR(x)} 🟥</th><td>${L2(multiples(x, 8))}، …</td></tr><tr><th>مضاعفاتُ ${AR(y)} 🟦</th><td>${L2(multiples(y, 8))}، …</td></tr><tr><th>(م.م.أ)</th><td><b>${AR(L)}</b> — أوّلُ موضعٍ يلتقي فيه المربّعانِ معًا</td></tr></table>`; };
  $('[data-a="go"]', el).onclick = go; go();
}
const cmQ = (tag, nums, o = {}) => { const L = lcmN(nums); return lst(tag, o.text || `حدّدِ المضاعفاتِ المشتركةَ الثلاثةَ الأولى للأعداد: ${L2(nums)}`, [L, 2 * L, 3 * L], { skill: 'cm', sol: [...nums.map(n => `مضاعفاتُ ${AR(n)}: ${L2(multiples(n, Math.min(12, 3 * L / n)))}، …`), `المضاعفاتُ المشتركةُ الثلاثةُ الأولى: ${L2([L, 2 * L, 3 * L])}`], hints: ['اكتبْ مضاعفاتِ كلِّ عددٍ (من غيرِ الصفر).', 'ابحثْ عن الأعدادِ الموجودةِ في جميعِ القوائم.'], ...o }); };
const lcmQ = (tag, nums, o = {}) => { const L = lcmN(nums); return num(tag, o.text || `أوجدِ (م.م.أ) للأعداد: ${L2(nums)}`, L, { skill: 'lcm', sol: [...nums.map(n => `${AR(n)} = ${pfHTML(n)}`), `نضربُ العواملَ المشتركةَ مرّةً واحدةً في العواملِ المتبقّية: (م.م.أ) = ${AR(L)}`], hints: ['اكتبْ مضاعفاتِ العددِ الأكبرِ حتى تجدَ مضاعفًا يقبلُ القسمةَ على الأعدادِ الأخرى.', 'أو حلّلْ كلَّ عددٍ إلى عواملِه الأوّليّة، واستعملِ العاملَ المشتركَ مرّةً واحدة.'], mistakes: [[nums.reduce((a, b) => a * b, 1), nums.reduce((a, b) => a * b, 1) === L ? '' : 'هذا مضاعفٌ مشترك، لكنّه ليس الأصغر.'], [gcdN(nums), 'هذا القاسمُ المشتركُ الأكبر، والمطلوبُ المضاعفُ المشتركُ الأصغر.']].filter(m => m[1]), mount: nums.length === 2 && L <= 60 ? el => { el.innerHTML = '<button class="lnk">📏 أرني على خطِّ الأعداد</button>'; $('button', el).onclick = () => multTool(el, nums[0], nums[1]); } : undefined, ...o }); };
Object.assign(G, {
  cm(L) { const a = rnd(2, L ? 9 : 6); let b; do { b = rnd(2, L ? 12 : 8); } while (b === a); return cmQ('', [a, b]); },
  lcm(L) { const a = rnd(2, L ? 15 : 9); let b; do { b = rnd(2, L ? 18 : 10); } while (b === a); const N = [a, b]; if (L === 2) N.push(pick([3, 4, 5, 6])); return lcmQ('', [...new Set(N)]); }
});
Object.assign(GN, { cm: 'المضاعفات المشتركة', lcm: 'المضاعف المشترك الأصغر' });
