    if (/^\d*\.\d+$/.test(raw)) { const s = raw.startsWith('.') ? '0' + raw : raw, r = d2fFrac(s), g = gcd(r.N, r.D); h = `<div class="meta">آخرُ منزلةٍ: الأجزاءُ من ${DEN10(s.split('.')[1].length)}</div><div class="big">${A(s)} = ${r.w ? mixed(r.w, r.N, r.D) : fr(r.N, r.D)}${g > 1 ? ` = ${r.w ? mixed(r.w, r.n, r.d) : fr(r.n, r.d)}` : ''}</div>${g > 1 ? `<div class="meta">بالقسمةِ على (ق.م.أ) = ${AR(g)}</div>` : ''}`; }
